def validate_pinned_repository(repository: Path, expected_commit: str) -> str:
    """Require an exact Git commit and a clean tracked/untracked worktree."""
    commit = _git(repository, "rev-parse", "HEAD")
    if commit != expected_commit:
        raise RepositoryValidationError(
            f"repository commit mismatch: expected {expected_commit}, got {commit}"
        )
    if _git(repository, "status", "--porcelain", "--untracked-files=normal"):
        raise RepositoryValidationError("repository worktree must be clean before indexing")
    return commit

def preflight_embedding(provider: EmbeddingProvider) -> None:
    """Run only the approved local Ollama model-availability preflight."""
    if not isinstance(provider, OllamaEmbeddingProvider):
        return
    try:
        provider.preflight()
    except EmbeddingProviderError as error:
        if error.error_type == "ModelNotFound":
            raise IndexingCoordinatorError(
                "embedding_model_unavailable",
                (IndexingFailure("preflight", "ModelNotFound"),),
            ) from error
        raise IndexingCoordinatorError(
            "embedding_provider_unavailable",
            (IndexingFailure("preflight", error.error_type),),
        ) from error

