def doctor_cancel_appointment(self, day, curr_user):
    doctor = self.get_doctor_obj(curr_user)
    if doctor:
        doctor.decrement_visits()
        doctor.schedule.cancel_appointment(day)
        ids = doctor.appointments.cancel_appointment(day)
        if ids:
            while not ids.is_empty():
                patient_id = ids.dequeue()
                patient = self.get_patient_obj(patient_id)
                time = patient.appointments.canceled_by_doctor(day, curr_user)
                patient.appointments.cancel_appointment(day, time)
            return True

def cancel_appointment(self, day):
    if self.schedule[day]:
        for i in range(len(self.schedule[day])):
            if self.schedule[day][i] == "Available" or self.schedule[day][i] == "Not Available":
                self.schedule[day][i] = "canceled"
        return True
    return False

def book_search(request):
    query = None
    results = []
    results_1 = Book.objects.none()
    results_2 = Book.objects.none()

    if 'query' in request.GET:
        form = SearchForm(request.GET)
        if form.is_valid():
            query = form.cleaned_data['query']
            results_1 = Book.objects.annotate(similarity=TrigramSimilarity('title', query)).filter(
                similarity__gte=0.1).order_by('-similarity')
            results_2 = Book.objects.annotate(similarity=TrigramSimilarity('description', query)).filter(
                similarity__gte=0.1).order_by('-similarity')
            results = (results_1 | results_2).order_by('-similarity')

    context = {
        'query': query,
        'results': results,
    }
    return render(request, "store/search.html", context)

def all_books(request):
    books = Book.objects.all()
    paginator = Paginator(books, 12)
    page_num = request.GET.get('page')
    try:
        books = paginator.page(page_num)
    except PageNotAnInteger:
        books = paginator.page(1)
    except EmptyPage:
        books = paginator.page(paginator.num_pages)

    return render(request, 'store/all_books.html', {'books': books})

