def _snapshot_preserved(self, snapshot: dict[str, Any] | None) -> bool:
    if snapshot is None:
        return False
    project_id = int(snapshot["project_id"])
    try:
        chunks = tuple(sorted(chunk.chunk_id for chunk in self.store.list_chunks(project_id)))
        vectors = self.collection(project_id).list_ids()
    except (StorageError, VectorIndexError):
        return False
    expected = tuple(snapshot["chunk_ids"])
    if chunks != expected or vectors != expected:
        return False
    generation = snapshot.get("vector_generation")
    if generation is None:
        return True
    project = self.store.get_project(project_id)
    if project is None or project.vector_generation != generation:
        return False
    try:
        return self.collection(project_id).active_generation() == generation
    except VectorIndexError:
        return False

def doctor_cancel_appointment(self, day, curr_user):
    doctor = self.get_doctor_obj(curr_user)
    if doctor:
        doctor.decrement_visits()
        doctor.schedule.cancel_appointment(day)
        ids = doctor.appointments.cancel_appointment(day)
        if ids:
            while not ids.is_empty():
                patient_id = ids.dequeue()
                patient = self.get_patient_obj(patient_id)
                time = patient.appointments.canceled_by_doctor(day, curr_user)
                patient.appointments.cancel_appointment(day, time)
            return True

def cancel_appointment(self, day):
    if self.schedule[day]:
        for i in range(len(self.schedule[day])):
            if self.schedule[day][i] == "Available" or self.schedule[day][i] == "Not Available":
                self.schedule[day][i] = "canceled"
        return True
    return False

def cancel_appointment(self, day):
    queue = Queue()
    if day in self.appointments:
        for time in range(len(self.appointments[day])):
            if self.appointments[day][int(time) - 1]:
                patient_id = self.appointments[day][int(time) - 1]
                queue.enqueue(patient_id)
                self.create_canceled(day, int(time) + 1, patient_id)
                self.appointments[day][int(time) - 1] = None
        return queue

