def _index_snapshot(self, project_id: int | None) -> dict[str, Any] | None:
    if project_id is None:
        return None
    try:
        chunk_ids = tuple(sorted(chunk.chunk_id for chunk in self.store.list_chunks(project_id)))
        vector_ids = self.collection(project_id).list_ids()
    except (StorageError, VectorIndexError):
        return None
    project = self.store.get_project(project_id)
    if project is None or set(chunk_ids) != set(vector_ids):
        return None
    if project.vector_generation is not None:
        try:
            generation = self.collection(project_id).active_generation()
        except VectorIndexError:
            return None
        if generation != project.vector_generation:
            return None
    return {"project_id": project_id, "chunk_ids": chunk_ids, "vector_generation": project.vector_generation}

def speciality_city(self, city, speciality):  # displays doctors by city and speciality
    array = DynamicArray()
    if city in self.table:
        if speciality in self.table[city]:
            if self.table[city][speciality]:
                sll = self.table[city][speciality]
                for node in sll:
                    if node.data in self.doctors:
                        array.append(self.doctors[node.data])
    return array

def rehashing(self, new_array):
    m = len(self.array)
    for item in self.array:
        if item and item != "deleted":
            for i in range(m):
                index = self.hash_function(item.key, i)
                if new_array[index] is None:
                    new_array[index] = item
                    break

    return new_array

def search(self, key):
    m = self.table_size
    arr = self.array

    for i in range(m):
        index = self.hash_function(key, i)
        item = arr[index]
        if item and item != "deleted":
            if item.key == key:
                return index
    return None

